const source = $('Build Gemini Interpreter Prompt').first().json.sourceInput || {};
const current = $input.first().json || {};

if (current.error) {
  return [{ json: { ...source, llmMeta: { ok: false, provider: 'gemini', error: String(current.error).slice(0, 500) } } }];
}

const parsed = current.output && typeof current.output === 'object' ? current.output : current;
if (!parsed || typeof parsed !== 'object' || parsed.mechanicalDiagnosisProduced !== false) {
  return [{ json: { ...source, llmMeta: { ok: false, provider: 'gemini', error: 'INVALID_OR_UNSAFE_INTERPRETATION' } } }];
}

return [{
  json: {
    ...source,
    llmInterpretation: parsed,
    llmMeta: {
      ok: true,
      provider: 'gemini',
      model: 'models/gemini-2.5-flash'
    }
  }
}];
